function recoverPenetration(){
 for(let pass=0;pass<8;pass++){let moved=false;for(const c of allColliders(s.pos)){const b=c.box,lo=new THREE.Vector3(b.min.x-playerBodyRadius(),b.min.y-playerBodyHeight(),b.min.z-playerBodyRadius()),hi=new THREE.Vector3(b.max.x+playerBodyRadius(),b.max.y+ROOF_CLEARANCE,b.max.z+playerBodyRadius());if(s.pos.x<=lo.x||s.pos.x>=hi.x||s.pos.y<=lo.y||s.pos.y>=hi.y||s.pos.z<=lo.z||s.pos.z>=hi.z)continue;
 const exits=[['x',lo.x-.025,s.pos.x-lo.x],['x',hi.x+.025,hi.x-s.pos.x],['y',hi.y+.025,hi.y-s.pos.y],['z',lo.z-.025,s.pos.z-lo.z],['z',hi.z+.025,hi.z-s.pos.z]].sort((a,b)=>a[2]-b[2]);s.pos[exits[0][0]]=exits[0][1];s.vel[exits[0][0]]=0;moved=true;markCollision('OVERLAP RECOVERED')}if(!moved)break}
}
